<?php
function render_page(string $page): void {
    if(in_array($page,['home','about','guide','privacy','login','activate','employer','404'],true)){render_public($page);return;}
    if(in_array($page,['alumni_home','alumni_profile','survey'],true)){require_role('alumni');begin_page(ucwords(str_replace('_',' ',$page)),$page);show_flash();render_alumni($page);end_page();return;}
    admin_access();begin_page(ucwords(str_replace('_',' ',$page)),$page);show_flash();render_admin($page);end_page();
}
function render_public(string $page): void {
    begin_page(ucwords($page),$page,true);
    if($page==='home'){
        $period=current_period();$alumni=(int)val('SELECT COUNT(*) FROM alumni');$responses=(int)val("SELECT COUNT(DISTINCT alumni_id) FROM responses WHERE status='final'");$percent=percentage($responses,max($alumni,1));$companies=(int)val('SELECT COUNT(DISTINCT company_name) FROM employer_responses WHERE verified=1');
         $hero=setting('hero_image');$heroFile=$hero&&preg_match('/^[a-z_]+_[a-f0-9]{24}\.(png|jpg|webp)$/',$hero)?'assets/uploads/'.$hero:'';
        echo '<section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><span class="hero-kicker">✦ ALUMNI BERDAYA · KAMPUS BERKUALITAS</span><h1>Jejak Alumni untuk <span>Masa Depan</span> yang Lebih Baik</h1><p>Tracer Study membantu perguruan tinggi memahami perjalanan lulusan, relevansi pendidikan, dunia kerja, dan peningkatan kualitas akademik.</p><div class="hero-actions"><a class="btn btn-gold" href="'.url(auth()?(admin_role()?'admin_dashboard':'survey'):'activate').'">Isi Tracer Study Sekarang ↗</a><a class="btn btn-outline-light" href="'.url('guide').'">Pelajari Panduan</a></div><div class="hero-signal">✓ Survei berbasis data &nbsp; ✓ Privasi terlindungi &nbsp; ✓ Mudah diakses</div></div><div class="hero-art'.($heroFile?' has-photo':'').'" '.($heroFile?'style="background-image:url('.esc($heroFile).')"':'').' aria-hidden="true"><div class="hero-ring"></div><div class="hero-building">▥</div><div class="hero-hat">🎓</div><div class="hero-art-title">ALUMNI<br>BERKARYA</div><div class="hero-art-sub">Masa depan dimulai dari jejak Anda.</div><div class="hero-decoration one">✦</div><div class="hero-decoration two">✧</div></div></div></section>';
        echo '<section class="wrap public-stats">'.stat_card('Total Alumni',number_format($alumni,0,',','.'),'users','Database lulusan','green').stat_card('Respon Kuesioner',number_format($responses,0,',','.'),'check','Seluruh survei','blue').stat_card('Partisipasi',$percent,'chart','Dari seluruh alumni','gold').stat_card('Perusahaan Penilai',number_format($companies,0,',','.'),'company','Penilaian terverifikasi','purple').'</section>';
        echo '<section class="wrap public-section"><div class="section-intro"><span class="eyebrow">LANGKAH MUDAH</span><h2>Isi Tracer Study dalam 4 langkah</h2><p>Partisipasi alumni membantu kampus mengevaluasi mutu lulusan dan menyesuaikan kurikulum.</p></div><div class="steps">';foreach([['01','Aktivasi / Login','Gunakan NIM dan kode akses dari pengelola.'],['02','Konfirmasi Biodata','Periksa kontak dan informasi pendidikan Anda.'],['03','Isi Kuesioner','Lengkapi pekerjaan, kompetensi, dan masukan.'],['04','Kirim Jawaban','Periksa kembali lalu submit jawaban.']] as $s)echo '<div class="step-card"><span>'.$s[0].'</span><h3>'.esc($s[1]).'</h3><p>'.esc($s[2]).'</p></div>';echo '</div></section>';
        echo '<section class="wrap feature-banner"><div><span class="eyebrow">KOLABORASI KAMPUS & INDUSTRI</span><h2>Anda mempekerjakan alumni kami?</h2><p>Berikan penilaian kompetensi dan masukan untuk perbaikan proses pembelajaran.</p></div><a class="btn btn-gold" href="'.url('employer').'">Isi Survei Pengguna Lulusan →</a></section>';
        if($period)echo '<div class="wrap period-public">Periode survei aktif: <b>'.esc($period['name']).'</b> · '.esc($period['start_date']).' sampai '.esc($period['end_date']).'</div>';
    }
    elseif($page==='login'){
        echo '<div class="auth-area"><div class="auth-art"><div class="auth-art-icon">🎓</div><h2>Selamat datang kembali</h2><p>Masuk ke portal Tracer Study untuk melanjutkan kontribusi Anda terhadap perkembangan kualitas kampus.</p><div class="auth-art-bottom">DATA ALUMNI · ANALITIK · DAMPAK</div></div><div class="auth-form"><span class="eyebrow">PORTAL TERINTEGRASI</span><h1>Masuk ke Akun</h1><p class="muted">Gunakan email dan password yang telah terdaftar.</p>';show_flash();echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="login">'.form_label('Alamat email','<input name="email" type="email" required autocomplete="username" placeholder="nama@email.com">',true).form_label('Password','<input id="login-password" name="password" type="password" required autocomplete="current-password" placeholder="••••••••••">',true).'<button class="btn btn-primary full">Masuk ke Dashboard →</button></form><div class="auth-note">Belum memiliki akun alumni? <a href="'.url('activate').'">Aktivasi dengan kode akses</a></div><div class="auth-note muted">Lupa password? Hubungi admin Tracer Study untuk proses reset yang terverifikasi.</div></div></div>';
    }
    elseif($page==='activate'){
        echo '<section class="auth-center"><div class="auth-card"><span class="eyebrow">AKTIVASI ALUMNI</span><h1>Aktivasi Akun Alumni</h1><p class="muted">Masukkan NIM dan kode akses yang diberikan secara pribadi oleh pengelola Tracer Study.</p>';show_flash();echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="activate"><div class="form-grid">'.form_label('NIM','<input name="nim" required maxlength="40">',true).form_label('Kode Akses Alumni','<input name="invite_code" required maxlength="30" autocomplete="off">',true).form_label('Email Sesuai Data Kampus','<input type="email" name="email" required>',true).form_label('Buat Password (min. 10 karakter)','<input type="password" name="password" minlength="10" required autocomplete="new-password">',true).'</div><button class="btn btn-primary">Aktivasi dan Masuk →</button></form><p class="muted">Belum menerima kode? Hubungi operator program studi. Kode tidak ditampilkan di website demi keamanan.</p></div></section>';
    }
    elseif($page==='employer'){render_employer_form();}
    elseif($page==='about'){echo '<section class="wrap content-public"><span class="eyebrow">TENTANG PROGRAM</span><h1>Tracer Study Perguruan Tinggi</h1><p>Tracer Study adalah survei sistematis kepada alumni untuk melihat transisi dari pendidikan tinggi ke dunia kerja, kelanjutan studi, serta masukan bagi pengembangan kurikulum, layanan karier, dan penjaminan mutu perguruan tinggi.</p><div class="steps">';foreach([['✓','Pemantauan Lulusan','Mengetahui status kerja, wirausaha, studi, dan pencarian pekerjaan.'],['▥','Evaluasi Kurikulum','Mengukur kesesuaian kompetensi dengan kebutuhan pengguna lulusan.'],['◉','Data untuk Keputusan','Menyajikan laporan agregat per program studi dan periode.']] as $s)echo '<div class="step-card"><span>'.$s[0].'</span><h3>'.$s[1].'</h3><p>'.$s[2].'</p></div>';echo '</div></section>';}
    elseif($page==='guide'){echo '<section class="wrap content-public"><span class="eyebrow">PANDUAN PENGISIAN</span><h1>Panduan Alumni</h1><div class="article-card"><ol><li>Hubungi pengelola untuk memperoleh <b>kode aktivasi pribadi</b> bila akun belum aktif.</li><li>Klik <b>Aktivasi</b>, masukkan NIM, kode akses, email yang terdaftar, dan buat password.</li><li>Masuk lalu perbarui kontak di menu Profil Alumni.</li><li>Pilih <b>Isi Kuesioner</b> dan lengkapi lima tahap, termasuk kondisi setelah lulus dan penilaian kompetensi.</li><li>Gunakan tombol Simpan & Lanjutkan untuk menyimpan draft setiap tahap.</li><li>Periksa ringkasan dan klik <b>Kirim Jawaban Final</b>. Respons terkunci setelah dikirim.</li></ol><p>Bila data angkatan/prodi kurang sesuai, minta operator melakukan perbaikan berdasarkan data akademik.</p></div></section>';}
    elseif($page==='privacy'){echo '<section class="wrap content-public"><h1>Privasi dan Pengelolaan Data</h1><div class="article-card"><p>Data individu digunakan untuk keperluan penelusuran lulusan dan evaluasi internal perguruan tinggi. Pengelola bertanggung jawab mengatur akses, memperoleh dasar pemrosesan yang sah, dan menetapkan kebijakan retensi sesuai peraturan yang berlaku.</p><p>Hasil pada portal publik ditampilkan secara agregat. Akses individu diberikan berdasarkan peran. Data survei pengguna lulusan ditinjau sebelum masuk laporan.</p><p>Untuk permintaan koreksi atau penghapusan data yang diperbolehkan, hubungi pengelola melalui '.esc(setting('contact_email','admin kampus')).'.</p></div></section>';}
    else {http_response_code(404);echo '<section class="wrap content-public"><h1>Halaman tidak ditemukan</h1><a class="btn btn-primary" href="'.url('home').'">Ke Beranda</a></section>';}
    end_page(true);
}
function render_employer_form(): void {
    echo '<section class="wrap content-public"><span class="eyebrow">EMPLOYER SATISFACTION SURVEY</span><h1>Survei Kepuasan Pengguna Lulusan</h1><p>Penilaian 1 = sangat kurang, 5 = sangat baik. Jawaban akan diverifikasi pengelola sebelum masuk hasil analitik.</p>';show_flash();echo '<form class="article-card" method="post">'.csrf_field().'<input type="hidden" name="action" value="employer_submit"><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><h3>Identitas Responden</h3><div class="form-grid">';
    foreach([['company_name','Nama Perusahaan / Institusi',true],['respondent_name','Nama Penilai',true],['respondent_position','Jabatan Penilai',false],['email','Email Penilai',false],['phone','Telepon (opsional)',false],['graduate_name','Nama Alumni yang Dinilai',false]] as [$key,$label,$required])echo form_label($label,'<input name="'.$key.'" '.($key==='email'?'type="email"':'').($required?' required':'').'>',$required);
    echo form_label('Program Studi Alumni',select_html('prodi_id',prodi_options()));echo '</div><h3>Penilaian Kompetensi (Skala 1–5)</h3><div class="rating-grid">';
    foreach(['ethics'=>'Etika dan Integritas','expertise'=>'Keahlian Sesuai Bidang','language'=>'Bahasa Asing','technology'=>'Teknologi Informasi','communication'=>'Komunikasi','teamwork'=>'Kerja Sama Tim','development'=>'Pengembangan Diri'] as $key=>$label)echo form_label($label,select_html($key,[''=>'Pilih nilai','1'=>'1 · Sangat Kurang','2'=>'2 · Kurang','3'=>'3 · Cukup','4'=>'4 · Baik','5'=>'5 · Sangat Baik'],null,'required'),true);
    echo '</div>'.form_label('Saran untuk Perguruan Tinggi','<textarea name="comment" rows="4" maxlength="2000" placeholder="Tulis kebutuhan kompetensi dan saran pengembangan kurikulum..."></textarea>').'<button class="btn btn-primary">Kirim Penilaian →</button></form></section>';
}
function alumni_record(): array {$u=require_role('alumni');$a=one('SELECT a.*,p.name AS prodi_name FROM alumni a JOIN programs p ON p.id=a.prodi_id WHERE a.user_id=?',[$u['id']]);if(!$a)throw new RuntimeException('Profil alumni tidak ditemukan.');return $a;}
function render_alumni(string $page): void {
    $a=alumni_record();$p=current_period();$eligible=$p&&(int)$a['graduation_year']>=(int)$p['graduation_year_min']&&(int)$a['graduation_year']<=(int)$p['graduation_year_max'];$r=$eligible?respond_for((int)$a['id'],(int)$p['id']):null;
    if($page==='alumni_home'){
        page_head('Dashboard Alumni','Selamat datang, '.$a['name'].'. Terima kasih menjadi bagian dari peningkatan mutu pendidikan.');
        echo '<div class="stats-grid">'.stat_card('NIM',$a['nim'],'user','Nomor Induk Mahasiswa','green').stat_card('Tahun Lulus',$a['graduation_year'],'cap',$a['prodi_name'],'blue').stat_card('Status Kuesioner',$r&&$r['status']==='final'?'Selesai':($r?'Draft':'Belum Isi'),'form',$p['name']??'Belum ada survei aktif','gold').'</div>';
        echo '<div class="two-col"><div class="panel"><h2>Perjalanan Tracer Study Anda</h2><div class="alumni-journey">';foreach([['1','Verifikasi Biodata','Periksa data akademik dan kontak.'],['2','Isi Kuesioner','Ceritakan aktivitas Anda setelah lulus.'],['3','Kirim & Selesai','Kontribusi Anda akan masuk ke analitik kampus.']] as $s)echo '<div class="journey-item"><span>'.$s[0].'</span><div><b>'.$s[1].'</b><p>'.$s[2].'</p></div></div>';echo '</div>';
        if(!$p)echo '<div class="notice">Belum ada periode survei yang diaktifkan oleh admin.</div>';
        elseif(!$eligible)echo '<div class="notice">Tahun kelulusan Anda belum menjadi target survei ini.</div>';
        elseif($r&&$r['status']==='final')echo '<div class="alert alert-success">✓ Terima kasih! Jawaban final diterima pada '.esc($r['submitted_at']).'.</div>';
        elseif(!period_open($p))echo '<div class="notice">Periode survei belum dibuka atau telah berakhir.</div>';
        else echo '<a href="'.url('survey').'" class="btn btn-primary">'.($r?'Lanjutkan Kuesioner':'Mulai Isi Kuesioner').' →</a>';
        echo '</div><div class="panel"><h2>Identitas Alumni</h2><dl class="profile-list"><dt>Nama</dt><dd>'.esc($a['name']).'</dd><dt>NIM</dt><dd>'.esc($a['nim']).'</dd><dt>Program Studi</dt><dd>'.esc($a['prodi_name']).'</dd><dt>Tahun Lulus</dt><dd>'.esc($a['graduation_year']).'</dd><dt>Email</dt><dd>'.esc($a['email']).'</dd><dt>Telepon</dt><dd>'.esc($a['phone']?:'Belum diisi').'</dd></dl><a class="btn btn-light" href="'.url('alumni_profile').'">Perbarui Kontak →</a></div></div>';
    }
    elseif($page==='alumni_profile'){
        page_head('Profil Alumni','Data akademik bersumber dari admin. Alumni dapat memperbarui data kontak pribadi.');echo '<div class="panel form-panel"><h2>Identitas & Kontak</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="save_profile"><div class="form-grid">';
        foreach(['Nama Lengkap'=>$a['name'],'NIM'=>$a['nim'],'Program Studi'=>$a['prodi_name'],'Tahun Lulus'=>$a['graduation_year'],'Email'=>$a['email']] as $label=>$value)echo form_label($label,'<input value="'.esc($value).'" disabled>');
        echo form_label('Nomor Telepon / WhatsApp','<input name="phone" value="'.esc($a['phone']).'" maxlength="30">').form_label('Kota Domisili','<input name="city" value="'.esc($a['city']).'" maxlength="120">').form_label('Jenis Kelamin',select_html('gender',[''=>'Pilih','L'=>'Laki-laki','P'=>'Perempuan'],$a['gender']));echo '</div><button class="btn btn-primary">Simpan Profil</button></form><hr><h2>Ubah Password</h2><form method="post">'.csrf_field().'<input type="hidden" name="action" value="change_password"><div class="form-grid">'.form_label('Password Lama','<input type="password" required name="old_password">').form_label('Password Baru (min. 12 karakter)','<input type="password" minlength="12" required name="new_password">').'</div><button class="btn btn-light">Ubah Password</button></form></div>';
    }
    elseif($page==='survey'){render_survey($a,$p,$r,$eligible);}
}
function render_survey(array $a,?array $p,?array $r,bool $eligible): void {
    page_head('Kuesioner Tracer Study','Lengkapi survei secara bertahap. Setiap tahap akan tersimpan sebagai draft.');
    if(!$p||!$eligible){echo '<div class="notice">Anda belum termasuk target survei aktif. Hubungi pengelola.</div>';return;}
    if($r&&$r['status']==='final'){echo '<div class="alert alert-success">Kuesioner sudah selesai dan tidak dapat diedit lagi. Terima kasih atas partisipasi Anda.</div>';return;}
    if(!period_open($p)){echo '<div class="notice">Periode pengisian belum dibuka atau telah berakhir.</div>';return;}
    $step=max(1,min(5,(int)($_GET['step']??($r?$r['progress']:1))));$statuses=statuses();
    $answers=$r?array_column(all('SELECT question_id,answer FROM answers WHERE response_id=?',[$r['id']]),'answer','question_id'):[];
    $names=['Biodata','Status Lulusan','Aktivitas Setelah Lulus','Kompetensi','Review & Kirim'];
    echo '<div class="survey-layout"><aside class="survey-progress"><h3>Tahapan Pengisian</h3>';foreach($names as $i=>$name){$number=$i+1;echo '<a class="progress-item '.($step===$number?'current':'').'" href="'.url('survey',['step'=>$number]).'"><span>'.$number.'</span><div><b>'.esc($name).'</b><small>'.($number===$step?'Sedang diisi':'Klik untuk melihat').'</small></div></a>';}echo '<div class="progress-tip">ⓘ Pastikan data yang Anda isi sesuai kondisi aktual.</div></aside><div class="panel survey-panel"><div class="survey-top"><span class="eyebrow">LANGKAH '.$step.' DARI 5</span><h2>'.esc($names[$step-1]).'</h2><p class="muted">Periode: '.esc($p['name']).'</p></div>';
    if($step<=4)echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="save_survey"><input type="hidden" name="step" value="'.$step.'"><div class="form-grid">';
    if($step===1){
        foreach(['Nama Lengkap'=>$a['name'],'NIM'=>$a['nim'],'Program Studi'=>$a['prodi_name'],'Tahun Lulus'=>$a['graduation_year']] as $label=>$value)echo form_label($label,'<input disabled value="'.esc($value).'">');
        echo form_label('WhatsApp','<input name="phone" value="'.esc($a['phone']).'">').form_label('Kota Domisili','<input name="city" value="'.esc($a['city']).'">').form_label('Jenis Kelamin',select_html('gender',[''=>'Pilih','L'=>'Laki-laki','P'=>'Perempuan'],$a['gender']));
    }
    if($step===2){echo '<div class="field span-2"><span>Status Utama Setelah Lulus <em>*</em></span><p class="muted">Pilih kondisi Anda saat ini atau aktivitas utama setelah lulus.</p>'.select_html('employment_status',[''=>'-- Pilih Status --']+$statuses,$r['employment_status']??'', 'required').'</div>';}
    if($step===3){
        $status=$r['employment_status']??'';echo '<div class="field span-2"><span>Status Saat Ini</span><div class="notice">'.esc($statuses[$status]??'Belum dipilih').'</div><a href="'.url('survey',['step'=>2]).'">Ubah status →</a></div>';
        if(!$status){echo '</div><div class="notice">Silakan lengkapi status pada tahap 2 terlebih dahulu.</div></form></div></div>';return;}
        $input=function(string $key,string $label,string $type='text')use($r){return form_label($label,'<input type="'.$type.'" name="'.$key.'" value="'.esc($r[$key]??'').'" '.($type==='number'?'min="0" step="1"':'').'>');};
        if($status==='bekerja'){echo $input('company_name','Nama Perusahaan / Instansi').$input('company_sector','Bidang Usaha').$input('position','Jabatan / Posisi').$input('company_city','Kota Tempat Bekerja');echo form_label('Jenis Pekerjaan',select_html('employment_type',[''=>'Pilih','pns'=>'PNS / ASN','swasta'=>'Pegawai Swasta','bumn'=>'BUMN / BUMD','kontrak'=>'Kontrak / Freelance','lainnya'=>'Lainnya'],$r['employment_type']??''));}
        if($status==='wirausaha'){echo $input('business_name','Nama Usaha').$input('business_sector','Bidang Wirausaha').$input('company_city','Kota Usaha');}
        if($status==='studi'){echo $input('study_university','Perguruan Tinggi Lanjutan').$input('study_program','Program Studi Lanjutan');}
        if(in_array($status,['bekerja','wirausaha'],true)){
            echo $input('first_job_months','Masa Tunggu Mulai Bekerja / Berusaha (bulan)','number').$input('monthly_income','Penghasilan Bulanan (Rupiah)','number');
            echo form_label('Kesesuaian Bidang Pekerjaan dengan Keilmuan',select_html('relevance',[''=>'Pilih','sangat_sesuai'=>'Sangat Sesuai','sesuai'=>'Sesuai','kurang'=>'Kurang Sesuai','tidak'=>'Tidak Sesuai'],$r['relevance']??''));
        }
        echo $input('job_search_before','Bulan Mencari Pekerjaan Sebelum Lulus','number').$input('job_search_after','Bulan Mencari Pekerjaan Setelah Lulus','number');
    }
    if($step===4){
        echo '<div class="field span-2"><div class="notice">Nilai 1 = sangat rendah, 5 = sangat tinggi. Kolom kiri menilai penguasaan saat ini, kolom kanan menilai kontribusi pembelajaran di kampus.</div></div>';
        foreach(['ethics'=>'Etika','expertise'=>'Keahlian Bidang Ilmu','language'=>'Bahasa Asing','it'=>'Teknologi Informasi','communication'=>'Komunikasi','teamwork'=>'Kerja Sama Tim','development'=>'Pengembangan Diri'] as $key=>$label){
            foreach(['competency'=>'Penguasaan','college'=>'Kontribusi Kampus'] as $prefix=>$group){$field=$prefix.'_'.$key;echo form_label($label.' · '.$group,select_html($field,[''=>'Pilih nilai','1'=>'1 · Sangat Rendah','2'=>'2 · Rendah','3'=>'3 · Cukup','4'=>'4 · Baik','5'=>'5 · Sangat Baik'],$r[$field]??'', 'required'),true);}
        }
        echo '</div><div class="form-grid"><div class="span-2">'.form_label('Saran Perbaikan untuk Perguruan Tinggi','<textarea rows="3" name="suggestions">'.esc($r['suggestions']??'').'</textarea>').'</div>';
        $status=$r['employment_status']??'';$questions=all('SELECT * FROM questions WHERE is_active=1 AND (period_id IS NULL OR period_id=?) AND (only_status=\'\' OR only_status=?) ORDER BY sort_order,id',[$p['id'],$status]);
        foreach($questions as $q){$field='q_'.$q['id'];$old=$answers[$q['id']]??'';$required=$q['is_required']?'required':'';
            if($q['type']==='select'){$options=[''=>'Pilih jawaban']+array_combine($choices=json_decode((string)$q['options_json'],true)?:[],$choices);$inp=select_html($field,$options,$old,$required);}
            elseif($q['type']==='textarea')$inp='<textarea name="'.$field.'" rows="3" '.$required.'>'.esc($old).'</textarea>';
            else $inp='<input type="'.($q['type']==='number'?'number':'text').'" name="'.$field.'" value="'.esc($old).'" '.$required.'>';
            echo '<div class="span-2">'.form_label($q['label'],$inp,(bool)$q['is_required']).'</div>';
        }
    }
    if($step<=4){echo '</div><div class="form-actions"><a class="btn btn-light" href="'.url('survey',['step'=>max(1,$step-1)]).'">← Sebelumnya</a><button class="btn btn-primary">Simpan & Lanjutkan →</button></div></form>';}
    if($step===5){
        if(!$r){echo '<div class="notice">Belum ada jawaban tersimpan.</div>';}else{
            echo '<div class="review-grid"><div><span>NIM</span><b>'.esc($a['nim']).'</b></div><div><span>Nama</span><b>'.esc($a['name']).'</b></div><div><span>Program Studi</span><b>'.esc($a['prodi_name']).'</b></div><div><span>Status Lulusan</span><b>'.esc($statuses[$r['employment_status']]??'Belum dipilih').'</b></div><div><span>Instansi / Usaha</span><b>'.esc($r['company_name']?:$r['business_name']?:'-').'</b></div><div><span>Masa Tunggu Kerja</span><b>'.esc($r['first_job_months']===null?'-':$r['first_job_months'].' bulan').'</b></div></div><div class="notice">Pastikan tahap 1–4 telah lengkap. Setelah dikirim, kuesioner terkunci dan tidak dapat diubah sendiri.</div><form method="post">'.csrf_field().'<input type="hidden" name="action" value="submit_survey"><div class="form-actions"><a class="btn btn-light" href="'.url('survey',['step'=>4]).'">← Kembali Periksa</a><button class="btn btn-gold" data-confirm="Kirim jawaban final? Setelah dikirim Anda tidak dapat mengeditnya.">✓ Kirim Jawaban Final</button></div></form>';
        }
    }
    echo '</div></div>';
}
function report_scope(?array $period,int $prodi=0): array {
    $u=admin_access();$own=own_prodi();if($own!==null)$prodi=$own;
    $conds=[];$params=[];
    if($period){$conds[]='a.graduation_year BETWEEN ? AND ?';$params[]=$period['graduation_year_min'];$params[]=$period['graduation_year_max'];}
    if($prodi){$conds[]='a.prodi_id=?';$params[]=$prodi;}
    return [$conds?' WHERE '.implode(' AND ',$conds):'',$params,$prodi];
}
function report_metrics(?array $period,int $prodi=0): array {
    if(!$period)return ['total'=>0,'final'=>0,'pending'=>0,'statuses'=>[],'trend'=>[],'waiting'=>[],'relevance'=>[],'programs'=>[],'avg_income'=>0];
    [$where,$args,$prodi]=report_scope($period,$prodi);$target=(int)val('SELECT COUNT(*) FROM alumni a'.$where,$args);
    $responders=(int)val('SELECT COUNT(*) FROM responses r JOIN alumni a ON a.id=r.alumni_id'.($where?$where.' AND ':' WHERE ').'r.period_id=? AND r.status=\'final\'',array_merge($args,[$period['id']]));
    $filters=$where?$where.' AND ':' WHERE ';
    $base=" FROM responses r JOIN alumni a ON a.id=r.alumni_id ".$filters."r.period_id=? AND r.status='final'";
    $pr=array_merge($args,[$period['id']]);
    $statuses=all('SELECT r.employment_status AS label,COUNT(*) AS amount'.$base.' GROUP BY r.employment_status',$pr);
    $trend=all("SELECT DATE_FORMAT(r.submitted_at,'%Y-%m') AS label,COUNT(*) AS amount".$base.' GROUP BY DATE_FORMAT(r.submitted_at,\'%Y-%m\') ORDER BY label',$pr);
    $waiting=all('SELECT CASE WHEN r.first_job_months < 3 THEN \'< 3 bulan\' WHEN r.first_job_months < 6 THEN \'3–5 bulan\' WHEN r.first_job_months <= 12 THEN \'6–12 bulan\' ELSE \'> 12 bulan\' END AS label,COUNT(*) AS amount'.$base." AND r.employment_status IN ('bekerja','wirausaha') AND r.first_job_months IS NOT NULL GROUP BY label ORDER BY MIN(r.first_job_months)",$pr);
    $relevance=all('SELECT r.relevance AS label,COUNT(*) AS amount'.$base." AND r.relevance<>'' GROUP BY r.relevance",$pr);
    $programs=all('SELECT p.name AS prodi,COUNT(*) AS total,SUM(CASE WHEN r.id IS NOT NULL THEN 1 ELSE 0 END) AS responded FROM alumni a JOIN programs p ON p.id=a.prodi_id LEFT JOIN responses r ON r.alumni_id=a.id AND r.period_id=? AND r.status=\'final\''.$where.' GROUP BY p.id,p.name ORDER BY p.name',array_merge([$period['id']],$args));
    $income=val('SELECT AVG(r.monthly_income)'.$base.' AND r.monthly_income > 0',$pr);
    return ['total'=>$target,'final'=>$responders,'pending'=>max(0,$target-$responders),'statuses'=>$statuses,'trend'=>$trend,'waiting'=>$waiting,'relevance'=>$relevance,'programs'=>$programs,'avg_income'=>(float)$income];
}
function display_bars(array $items,string $color='green',string $empty='Data belum tersedia'): void {
    if(!$items){empty_block($empty);return;}$max=max(array_map(fn($x)=>(int)$x['amount'],$items))?:1;
    echo '<div class="bar-list">';foreach($items as $x){$p=(int)round(100*((int)$x['amount'])/$max);echo '<div class="bar-row"><div class="bar-head"><span>'.esc($x['label']?:'Tidak diisi').'</span><b>'.number_format((int)$x['amount'],0,',','.').'</b></div><div class="bar-track"><div class="bar-fill '.$color.'" style="width:'.$p.'%"></div></div></div>';}echo '</div>';
}
function display_donut(array $items,int $total): void {
    if(!$total){empty_block('Belum ada respons final.');return;}
    $cols=['#068b64','#f3ac24','#397bd5','#8767d3','#ed756f','#97a8ae'];$sum=0;$segments=[];
    foreach($items as $i=>$it){$amount=(int)$it['amount'];$start=($sum/$total)*100;$sum+=$amount;$end=($sum/$total)*100;$segments[]=$cols[$i%count($cols)].' '.$start.'% '.$end.'%';}
    echo '<div class="donut-layout"><div class="donut" style="background:conic-gradient('.esc(implode(',',$segments)).')"><div class="donut-core"><b>'.number_format($total,0,',','.').'</b><small>Responden</small></div></div><div class="legend">';foreach($items as $i=>$it)echo '<div><span class="legend-dot" style="background:'.$cols[$i%count($cols)].'"></span><span>'.esc(statuses()[$it['label']]??ucwords(str_replace('_',' ',$it['label']))).'</span><b>'.percentage((int)$it['amount'],$total).'</b></div>';echo '</div></div>';
}
