function admin_responses(): void {
    $p=current_period();$pid=(int)($_GET['period_id']??($p['id']??0));$target=(string)($_GET['status']??'');$filter=(int)($_GET['prodi']??0);if(own_prodi())$filter=own_prodi();
    $conds=[];$args=[];if($pid){$conds[]='r.period_id=?';$args[]=$pid;}if($filter){$conds[]='a.prodi_id=?';$args[]=$filter;}if(in_array($target,['draft','final'],true)){$conds[]='r.status=?';$args[]=$target;}
    $where=$conds?' WHERE '.implode(' AND ',$conds):'';$pageNum=max(1,(int)($_GET['p']??1));$per=20;
    $total=(int)val('SELECT COUNT(*) FROM responses r JOIN alumni a ON a.id=r.alumni_id'.$where,$args);
    $records=all('SELECT r.*,a.nim,a.name,a.graduation_year,p.name AS prodi_name,pe.name AS period_name FROM responses r JOIN alumni a ON a.id=r.alumni_id JOIN programs p ON p.id=a.prodi_id JOIN periods pe ON pe.id=r.period_id'.$where.' ORDER BY r.updated_at DESC LIMIT '.(int)$per.' OFFSET '.(int)(($pageNum-1)*$per),$args);
    page_head('Monitoring Responden','Tinjau pengisian sementara dan jawaban yang sudah dikirim.');
    echo '<div class="panel"><form method="get" class="filter-bar filters-wide"><input type="hidden" name="page" value="admin_responses">'.admin_period_select($p).select_html('prodi',prodi_options(),$filter,own_prodi()?'disabled':'').select_html('status',[''=>'Semua Status','draft'=>'Draft','final'=>'Selesai'],$target).'<button class="btn btn-primary">Tampilkan</button></form><h2>Daftar Jawaban <span class="count">'.$total.'</span></h2><div class="table-scroll"><table><thead><tr><th>Alumni</th><th>Program Studi</th><th>Tahun</th><th>Status Lulusan</th><th>Progres</th><th>Tanggal</th></tr></thead><tbody>';foreach($records as $r)echo '<tr><td><b>'.esc($r['name']).'</b><small class="table-sub">'.esc($r['nim']).'</small></td><td>'.esc($r['prodi_name']).'</td><td>'.(int)$r['graduation_year'].'</td><td>'.esc(statuses()[$r['employment_status']]??'Belum diisi').'</td><td>'.status_chip($r['status']).' · '.(int)$r['progress'].'/5</td><td>'.esc($r['submitted_at']??$r['updated_at']).'</td></tr>';echo '</tbody></table></div>';if(!$records)empty_block('Belum ada jawaban untuk filter ini.');nav_pager($total,$per,$pageNum,['period_id'=>$pid,'prodi'=>$filter,'status'=>$target]);echo '</div>';
}
