function admin_reports(bool $printing=false): void {
    $period=current_period();$pid=(int)($_GET['period_id']??($period['id']??0));if($pid)$period=one('SELECT * FROM periods WHERE id=?',[$pid]);
    $prodi=(int)($_GET['prodi']??0);$m=report_metrics($period,$prodi);$params=['period_id'=>$pid,'prodi'=>own_prodi()??$prodi];
    page_head('Analitik & Laporan','Visualisasi hasil tracer study, capaian, dan rekonsiliasi data alumni.','<div class="action-row"><a class="btn btn-export" href="'.url('admin_reports',array_merge($params,['export'=>'xlsx'])).'">⇩ Excel</a><a class="btn btn-danger" href="'.url('admin_reports',array_merge($params,['export'=>'pdf'])).'">⇩ PDF</a>'.(role(['admin','operator'])?'<a class="btn btn-light" href="'.url('admin_reports',array_merge($params,['export'=>'details'])).'">⇩ Data Responden</a>':'').'<a class="btn btn-light" href="'.url('report_print',$params).'">▤ Cetak</a></div>');
    if(!$printing)echo '<form class="panel filter-bar filters-wide" method="get"><input type="hidden" name="page" value="admin_reports">'.admin_period_select($period).select_html('prodi',prodi_options(),own_prodi()??$prodi,own_prodi()?'disabled':'').'<button class="btn btn-primary">Tampilkan Data</button></form>';
    echo '<div class="stats-grid">'.stat_card('Total Alumni Target',number_format($m['total'],0,',','.'),'users','Sesuai filter','green').stat_card('Responden Final',number_format($m['final'],0,',','.'),'check','Jawaban lengkap','blue').stat_card('Tingkat Respons',percentage($m['final'],$m['total']),'chart','Capaian partisipasi','gold').stat_card('Penghasilan Rata-rata',money($m['avg_income']),'company','Responden berpenghasilan','purple').'</div>';
    echo '<div class="report-grid"><div class="panel"><h2>Masa Tunggu Kerja</h2><p class="muted">Alumni bekerja / berwirausaha yang mengisi masa tunggu</p>';display_bars($m['waiting'],'green');echo '</div><div class="panel"><h2>Kesesuaian Bidang Pekerjaan</h2><p class="muted">Persepsi kesesuaian pekerjaan dengan pendidikan</p>';display_bars(array_map(fn($x)=>['label'=>ucwords(str_replace('_',' ',$x['label'])),'amount'=>$x['amount']],$m['relevance']),'gold');echo '</div><div class="panel"><h2>Status Lulusan</h2>';display_donut($m['statuses'],$m['final']);echo '</div><div class="panel"><h2>Tren Responden</h2>';display_bars($m['trend'],'blue');echo '</div></div>';
    echo '<div class="panel"><div class="panel-head"><div><h2>Rekapitulasi per Program Studi</h2><p class="muted">Satu alumni dihitung satu kali per periode survei</p></div></div><div class="table-scroll"><table><thead><tr><th>No</th><th>Program Studi</th><th>Total Alumni Target</th><th>Responden Final</th><th>Belum Mengisi</th><th>Tingkat Respons</th></tr></thead><tbody>';
    foreach($m['programs'] as $i=>$p)echo '<tr><td>'.($i+1).'</td><td><b>'.esc($p['prodi']).'</b></td><td>'.(int)$p['total'].'</td><td>'.(int)$p['responded'].'</td><td>'.((int)$p['total']-(int)$p['responded']).'</td><td><span class="chip chip-good">'.percentage((int)$p['responded'],(int)$p['total']).'</span></td></tr>';
    echo '</tbody></table></div>';if(!$m['programs'])empty_block('Pilih periode survei dengan data alumni.');echo '</div>';
    $employerScores=report_employer_scores(own_prodi()??$prodi);
    echo '<div class="panel"><h2>Kepuasan Pengguna Lulusan</h2><p class="muted">Rata-rata penilaian terverifikasi, berdasarkan skala 1–5. Terpisah dari responden alumni.</p>';
    display_bars($employerScores,'green','Belum ada penilaian pengguna lulusan terverifikasi.');
    echo '</div><p class="report-disclaimer">Catatan: laporan ini merupakan ringkasan data internal aplikasi. Bukan bukti keberhasilan pengiriman data ke platform pelaporan nasional.</p>';
    if($printing)echo '<div class="panel"><button type="button" class="btn btn-primary" data-print>Cetak / Simpan PDF dari Browser</button></div>';
}
