function pending_alumni(?array $period): array {
    if(!$period)return [];
    $own=own_prodi();$prodi=$own??(int)($_GET['prodi']??0);
    $cond=$prodi?' AND a.prodi_id=?':'';$params=[$period['id'],$period['graduation_year_min'],$period['graduation_year_max']];if($prodi)$params[]=$prodi;
    return all("SELECT a.id,a.nim,a.name,a.phone,a.email,p.name AS prodi_name,r.status AS response_status FROM alumni a JOIN programs p ON p.id=a.prodi_id LEFT JOIN responses r ON r.alumni_id=a.id AND r.period_id=? WHERE a.graduation_year BETWEEN ? AND ? $cond AND (r.status IS NULL OR r.status<>'final') ORDER BY a.name LIMIT 1000",$params);
}
function admin_reminders(): void {
    admin_access('write');$p=current_period();$rows=pending_alumni($p);
    page_head('Pengingat Alumni','Tindak lanjut secara manual kepada alumni yang belum menyelesaikan survei.');
    if(!$p){echo '<div class="notice">Aktifkan periode survei untuk melihat alumni yang perlu dihubungi.</div>';return;}
    echo '<div class="stats-grid">'.stat_card('Periode Aktif',$p['name'],'period','Target '.$p['graduation_year_min'].' – '.$p['graduation_year_max'],'green').stat_card('Daftar Tindak Lanjut',count($rows),'bell','Maksimum 1.000 data','gold').'</div>';
    echo '<div class="panel"><div class="panel-head"><h2>Alumni Belum Mengirim</h2><a class="btn btn-export" href="'.url('admin_reminders',['export'=>'reminders']).'">⇩ Unduh CSV Kontak</a></div><p class="muted">Klik WhatsApp untuk membuka pesan siap kirim; aplikasi tidak mengirim pesan otomatis. Pastikan memperoleh persetujuan dan gunakan nomor sesuai kebijakan privasi institusi.</p><div class="table-scroll"><table><thead><tr><th>NIM</th><th>Nama</th><th>Program Studi</th><th>Status</th><th>Kontak</th><th>Pengingat</th></tr></thead><tbody>';
    foreach($rows as $a){$phone=safe_phone($a['phone']);if(str_starts_with($phone,'0'))$phone='62'.substr($phone,1);
        $message='Halo '.$a['name'].', kami mengundang Anda untuk melengkapi Tracer Study '.$p['name'].' melalui portal resmi kampus. Terima kasih atas partisipasi Anda.';
        $wa=($phone && strlen($phone)>=9 && strlen($phone)<=16)?'https://wa.me/'.$phone.'?text='.rawurlencode($message):'';
        echo '<tr><td>'.esc($a['nim']).'</td><td><b>'.esc($a['name']).'</b><small class="table-sub">'.esc($a['email']).'</small></td><td>'.esc($a['prodi_name']).'</td><td>'.esc($a['response_status']?:'Belum mengisi').'</td><td>'.esc($a['phone']?:'—').'</td><td>'.($wa?'<a class="btn btn-xs btn-primary" href="'.esc($wa).'" target="_blank" rel="noopener noreferrer">Hubungi WA ↗</a>':'Nomor tidak valid').'</td></tr>';
    }
    echo '</tbody></table></div>';if(!$rows)empty_block('Semua responden target telah selesai atau daftar kosong.');echo '</div>';
}

function report_employer_scores(int $prodi=0): array {
    if(own_prodi())$prodi=own_prodi();$sql='SELECT AVG(ethics) ethics,AVG(expertise) expertise,AVG(language) language,AVG(technology) technology,AVG(communication) communication,AVG(teamwork) teamwork,AVG(development) development FROM employer_responses WHERE verified=1';
    $params=[];if($prodi){$sql.=' AND prodi_id=?';$params[]=$prodi;}
    $r=one($sql,$params);$map=['ethics'=>'Etika','expertise'=>'Keahlian','language'=>'Bahasa Asing','technology'=>'Teknologi','communication'=>'Komunikasi','teamwork'=>'Kerja Sama','development'=>'Pengembangan Diri'];
    if(!$r||$r['ethics']===null)return [];
    $result=[];foreach($map as $key=>$name)$result[]=['label'=>$name.' · '.number_format((float)$r[$key],2,',','.').' / 5','amount'=>(int)round((float)$r[$key]*20)];return $result;
}
